@dataclass
class DatasetRecordConfig:
    # Dataset identifier. By convention it should match '{hf_username}/{dataset_name}' (e.g. `lerobot/test`).
    repo_id: str
    # A short but accurate description of the task performed during the recording (e.g. "Pick the Lego block and drop it in the box on the right.")
    single_task: str
    # Root directory where the dataset will be stored (e.g. 'dataset/path'). If None, defaults to $HF_LEROBOT_HOME/repo_id.
    root: str | Path | None = None
    # Limit the frames per second.
    fps: int = 30
    # Number of seconds for data recording for each episode.
    episode_time_s: int | float = 60
    # Number of seconds for resetting the environment after each episode.
    reset_time_s: int | float = 60
    # If True, the reset phase waits for the operator to press Enter instead of
    # running for a fixed `reset_time_s`. Useful when reset time varies widely.
    reset_wait_enter: bool = False
    # Number of episodes to record.
    num_episodes: int = 50
    # Encode frames in the dataset into video
    video: bool = True
    # Upload dataset to Hugging Face hub.
    push_to_hub: bool = True
    # Upload on private repository on the Hugging Face hub.
    private: bool = False
    # Add tags to your dataset on the hub.
    tags: list[str] | None = None
    # Number of subprocesses handling the saving of frames as PNG. Set to 0 to use threads only;
    # set to ≥1 to use subprocesses, each using threads to write images. The best number of processes
    # and threads depends on your system. We recommend 4 threads per camera with 0 processes.
    # If fps is unstable, adjust the thread count. If still unstable, try using 1 or more subprocesses.
    num_image_writer_processes: int = 0
    # Number of threads writing the frames as png images on disk, per camera.
    # Too many threads might cause unstable teleoperation fps due to main thread being blocked.
    # Not enough threads might cause low camera fps.
    num_image_writer_threads_per_camera: int = 4
    # Number of episodes to record before batch encoding videos
    # Set to 1 for immediate encoding (default behavior), or higher for batched encoding
    video_encoding_batch_size: int = 1
    # Video codec for encoding videos. Options: 'h264', 'hevc', 'libsvtav1', 'auto',
    # or hardware-specific: 'h264_videotoolbox', 'h264_nvenc', 'h264_vaapi', 'h264_qsv'.
    # Use 'auto' to auto-detect the best available hardware encoder.
    vcodec: str = "libsvtav1"
    # Enable streaming video encoding: encode frames in real-time during capture instead
    # of writing PNG images first. Makes save_episode() near-instant. More info in the documentation: https://huggingface.co/docs/lerobot/streaming_video_encoding
    streaming_encoding: bool = False
    # Maximum number of frames to buffer per camera when using streaming encoding.
    # ~1s buffer at 30fps. Provides backpressure if the encoder can't keep up.
    encoder_queue_maxsize: int = 30
    # Number of threads per encoder instance. None = auto (codec default).
    # Lower values reduce CPU usage, maps to 'lp' (via svtav1-params) for libsvtav1 and 'threads' for h264/hevc..
    encoder_threads: int | None = None
    # Rename map for the observation to override the image and state keys
    rename_map: dict[str, str] = field(default_factory=dict)

    def __post_init__(self):
        if self.single_task is None:
            raise ValueError("You need to provide a task as argument in `single_task`.")


# Per-frame subtask instructions, keyed by the keyboard digit the operator taps
# during recording. "{N}" placeholders are filled at runtime: pressing the bound
# key arms an "awaiting slot" state, and the operator then presses 'a', 'b', or
# 'c' to select slot 1, 2, or 3 respectively. The resolved string becomes the
# frame's "task" label. `RecordConfig.subtask_slot_n` is no longer used to
# pre-fill {N}; it only serves (like `enable_subtasks`) to turn the keymap on.
# Image-key rename map for openpi-style checkpoints. Some pi0.5 models were
# trained with the openpi naming convention (`base_0_rgb`, `*_wrist_0_rgb`)
# rather than the bi_so_follower-prefixed keys this codebase produces.
# When `image_keys_openpi_style=True` we hand the policy a renamed copy of
# the observation; the dataset path keeps the original keys.
BI_SO_TO_OPENPI_KEYS: dict[str, str] = {
    "observation.images.left_left_front":   "observation.images.left_wrist_0_rgb",
    "observation.images.right_right_front": "observation.images.right_wrist_0_rgb",
    "observation.images.left_top":          "observation.images.base_0_rgb",
}


# Single-camera-per-subtask masking. When `cam_mask_per_subtask=True`, the two
# inactive camera tensors are zeroed in `observation_frame` before each policy
# call. Used for single-camera checkpoints, which were trained
# with only the listed camera visible per subtask. Map: substring → active cam.
SUBTASK_ACTIVE_CAM: dict[str, str] = {
    "grasp the nearest blue thread":     "right_right_front",  # 1
    "place the gauze into slot":         "left_top",           # 2 + a/b/c
    "release the gauze by opening":      "right_right_front",  # 3
    "return the right arm to rest":      "right_right_front",  # 4
    "grasp the white edge":              "left_left_front",    # 5
    "grasp the exposed blue":            "right_right_front",  # 6
    "release the white edge by opening": "left_left_front",    # 7
    "release the white edge and return": "left_left_front",    # 8
    "return the left arm to rest":       "left_top",           # 9
}


SUBTASK_LABELS: dict[str, str] = {
    "0": "drop that subtask",                                                                                                    # DROP — marks previous incomplete task as bad
    "1": "grasp the nearest blue thread of the gauze from the green tray with the right arm and lift it",                        # RA_grab_and_lift
    "2": "lower and place the gauze into slot {N} with the right arm",                                                           # RA_place_to_slot
    "3": "release the gauze by opening the right gripper",                                                                       # RA_release
    "4": "return the right arm to rest position",                                                                                # RA_back
    "5": "grasp the white edge of the gauze with the left arm and lift it",                                                      # LA_grab_lift_edge
    "6": "grasp the exposed blue thread of the gauze with the right arm and lift it",                                            # RA_grab_blue
    "7": "release the white edge by opening the left gripper",                                                                   # LA_release
    "8": "release the white edge and return the left arm to rest position",                                                      # LA_drop_abort
    "9": "return the left arm to rest position",                                                                                 # LA_back
    "ra_home": "right arm hardcoded recovery to home",                                                                           # RA_hardcoded_home — triggers _ra_recovery interception (linear lerp, LA held at snapshot)
}

# Short TTS phrases read aloud when the operator presses a subtask key. Kept
# terse (1-3 words) so the speech can keep up with rapid presses. The slot
# chord ('a'/'b'/'c' after key 2) speaks its own "slot 1/2/3" confirmation.
SUBTASK_VOICES: dict[str, str] = {
    "0": "drop",
    "1": "right arm grab",
    "2": "place to slot",
    "3": "right arm release",
    "4": "right arm back",
    "5": "left arm grab",
    "6": "right arm grab blue",
    "7": "left arm release",
    "8": "drop and home",
    "9": "left arm back",
    "ra_home": "right arm hardcoded home",
}


def _build_active_subtasks(slot_n: int | None) -> dict[str, str]:
    # Returns the full label map. {N} placeholders are kept unresolved here;
    # `init_keyboard_listener` resolves them at runtime when the operator
    # presses 'a'/'b'/'c' after a slot-templated key.
    return dict(SUBTASK_LABELS)


DROP_LABEL = SUBTASK_LABELS["0"]
IDLE_LABEL = "gauze_placement"


def _clean_drop_segments(dataset) -> int:
    """Post-process the episode buffer after recording: for each 'drop that subtask'
    segment, relabel the preceding failed-action frames AND the drop frames to idle.
    Returns the number of frames relabeled."""
    buf = dataset.writer.episode_buffer
    if buf is None:
        return 0

    tasks = buf["task"]
    if DROP_LABEL not in tasks:
        return 0

    cleaned = 0
    i = len(tasks) - 1
    while i >= 0:
        if tasks[i] == DROP_LABEL:
            drop_end = i
            # Walk back through drop frames
            while i >= 0 and tasks[i] == DROP_LABEL:
                tasks[i] = IDLE_LABEL
                cleaned += 1
                i -= 1
            # Walk back through the preceding failed-action frames
            if i >= 0:
                failed_task = tasks[i]
                while i >= 0 and tasks[i] == failed_task:
                    tasks[i] = IDLE_LABEL
                    cleaned += 1
                    i -= 1
        else:
            i -= 1

    if cleaned > 0:
        logging.info(f"Post-process: relabeled {cleaned} drop+failed frames to idle")
    return cleaned


@dataclass
class RecordConfig:
    robot: RobotConfig
    dataset: DatasetRecordConfig
    # Whether to control the robot with a teleoperator
    teleop: TeleoperatorConfig | None = None
    # Whether to control the robot with a policy
    policy: PreTrainedConfig | None = None
    # Display all cameras on screen
    display_data: bool = False
    # Display data on a remote Rerun server
    display_ip: str | None = None
    # Port of the remote Rerun server
    display_port: int | None = None
    # Whether to  display compressed images in Rerun
    display_compressed_images: bool = False
    # Use vocal synthesis to read events.
    play_sounds: bool = True
    # Resume recording on an existing dataset.
    resume: bool = False
    # Action interpolation multiplier for smoother policy control (1=off, 2=2x, 3=3x)
    # Only applies when using a policy (not teleop)
    interpolation_multiplier: int = 1
    # When set, enables per-frame subtask labeling (keys 1-9 set the current
    # instruction during teleop). Also fills "{N}" in the "place the gauze into
    # slot {N}" subtask. Leave as None for datasets without slot semantics.
    subtask_slot_n: int | None = None
    # When True, enables the subtask labeling keymap even if subtask_slot_n is None
    # (useful for Task C where no slot is used but you still want 1/3/5/6/7 active).
    enable_subtasks: bool = False
    # Stable task-index ordering supplied by the SurgeCount collection wrapper.
    canonical_task_labels: list[str] | None = None
    # Single-cam mode: zero out non-active camera tensors per subtask before
    # passing to the policy. Used with checkpoints trained on per-subtask
    # camera masking (see SUBTASK_ACTIVE_CAM). Requires `enable_subtasks=true`
    # so that `events["current_task"]` reflects the operator's key press.
    cam_mask_per_subtask: bool = False
    # Rename observation image keys to the openpi convention (base_0_rgb,
    # *_wrist_0_rgb) before passing to the policy. The dataset still records
    # under the original bi_so_follower keys. Used for checkpoints trained on
    # openpi-style data with renamed camera features.
    image_keys_openpi_style: bool = False
    # Burst frame selection: at every Nth tick (matching policy.n_action_steps)
    # capture this many consecutive observations and keep the sharpest image
    # per camera (Laplacian variance). Used to skip flickered frames from
    # defective cameras. 0 disables (default; original camera flow unchanged).
    burst_select_n: int = 0
    # Path to a "key=value\n" home pose file (as produced by go_home.sh save).
    # If set, arms are driven to this pose between episodes before the reset
    # teleop phase begins, so the operator does not have to home manually.
    home_pose_file: str | None = None
    # Seconds to spend driving to the home pose between episodes. Keep short.
    home_duration_s: float = 2.0
    # Stop signal: action dimension index for the stop signal (e.g., 12 for 13-dim actions).
    # When set, the robot freezes after N consecutive frames with stop > 0.5.
    stop_signal_dim: int | None = None
    # Number of consecutive stop predictions needed to freeze the robot.
    stop_signal_threshold: int = 10
    # Lookahead scans a predicted chunk. Consecutive reproduces the original
    # manual controller's ten executed policy predictions above 0.5.
    stop_signal_mode: str = "lookahead"
    # Release entry points never recalibrate on connection.
    calibrate_on_connect: bool = False
    # Optional Claude-API high-level planner. When set to "claude", a ClaudePlanner
    # is invoked at each freeze boundary to pick the next subtask string. Leave as
    # None (default) to use the keyboard-only flow. The keyboard listener still
    # runs and always wins (last-writer on events["current_task"]).
    planner: str | None = None
    # If True, the planner observes and logs but does NOT inject into events.
    # Operator drives normally with the keyboard. Use this for dry-run validation.
    planner_dry_run: bool = False
    # Minimum seconds between consecutive planner calls.
    planner_cooldown_s: float = 1.5
    # Run a self-check pass after the initial subtask choice (extra API call).
    planner_self_check: bool = True
    # Directory for per-session JSONL planner traces.
    planner_log_dir: str | None = None
    # Claude model ID. Leave default unless you specifically want to override.
    planner_model: str = "claude-opus-4-7"
    # Vision-confidence guard for skill 1 (RA grab blue thread). If the
    # planner's most recent call scored visible_blue_confidence below this
    # threshold, skill 1 will be refused regardless of whether the trigger
    # came from the keyboard or the planner. pi0.5's skill-1 policy is known
    # to grasp the white part of the gauze when blue isn't accessible — this
    # guard prevents that. Set to 0.0 to disable.
    planner_blue_confidence_threshold: float = 0.4
    # Test mode (currently only honored by the gemini planner): when True,
    # planner decisions are written to events["pending_planner_decision"] and
    # the operator must press SPACE to confirm (or 1-9 to override). Robot
    # stays still while a decision is pending.
    planner_confirm_required: bool = False

    def __post_init__(self):
        # HACK: We parse again the cli args here to get the pretrained path if there was one.
        policy_path = parser.get_path_arg("policy")

        if policy_path:
            cli_overrides = parser.get_cli_overrides("policy")

            self.policy = PreTrainedConfig.from_pretrained(policy_path, cli_overrides=cli_overrides)
            self.policy.pretrained_path = policy_path

        if self.teleop is None and self.policy is None:
            raise ValueError("Choose a policy, a teleoperator or both to control the robot")

    @classmethod
    def __get_path_fields__(cls) -> list[str]:
        """This enables the parser to load config from the policy using `--policy.path=local/dir`"""
        return ["policy"]


""" --------------- record_loop() data flow --------------------------
       [ Robot ]
           V
     [ robot.get_observation() ] ---> raw_obs
           V
     [ robot_observation_processor ] ---> processed_obs
           V
     .-----( ACTION LOGIC )------------------.
     V                                       V
     [ From Teleoperator ]                   [ From Policy ]
     |                                       |
     |  [teleop.get_action] -> raw_action    |   [predict_action]
     |          |                            |          |
     |          V                            |          V
     | [teleop_action_processor]             |          |
     |          |                            |          |
     '---> processed_teleop_action           '---> processed_policy_action
     |                                       |
     '-------------------------.-------------'
                               V
                  [ robot_action_processor ] --> robot_action_to_send
                               V
                    [ robot.send_action() ] -- (Robot Executes)
                               V
                    ( Save to Dataset )
                               V
                  ( Rerun Log / Loop Wait )
"""


@safe_stop_image_writer
def record_loop(
    robot: Robot,
    events: dict,
    fps: int,
    teleop_action_processor: RobotProcessorPipeline[
        tuple[RobotAction, RobotObservation], RobotAction
    ],  # runs after teleop
    robot_action_processor: RobotProcessorPipeline[
        tuple[RobotAction, RobotObservation], RobotAction
    ],  # runs before robot
    robot_observation_processor: RobotProcessorPipeline[
        RobotObservation, RobotObservation
    ],  # runs after robot
    dataset: LeRobotDataset | None = None,
    teleop: Teleoperator | list[Teleoperator] | None = None,
    policy: PreTrainedPolicy | None = None,
    preprocessor: PolicyProcessorPipeline[dict[str, Any], dict[str, Any]] | None = None,
    postprocessor: PolicyProcessorPipeline[PolicyAction, PolicyAction] | None = None,
    control_time_s: int | None = None,
    single_task: str | None = None,
    display_data: bool = False,
    interpolator: ActionInterpolator | None = None,
    display_compressed_images: bool = False,
    stop_signal_dim: int | None = None,
    stop_signal_threshold: int = 10,
    stop_signal_mode: str = "lookahead",
    home_pose_file: str | None = None,
    enable_subtasks: bool = False,
    cam_mask_per_subtask: bool = False,
    image_keys_openpi_style: bool = False,
    burst_select_n: int = 0,
    planner: Any = None,  # ClaudePlanner | None — duck-typed to avoid hard import
    blue_confidence_threshold: float = 0.0,  # 0.0 = guard disabled
):
    stop_count = 0
    # Cache skill 1's training-time label once, used by the confidence guard.
    _skill_1_label = SUBTASK_LABELS.get("1")
    # Rolling window of recent stop-signal values (≈1 second @ fps Hz) for visualization.
    from collections import deque
    stop_signal_history: deque[float] = deque(maxlen=max(int(fps), 1))
    # Chunk-level stop-signal lookahead state. After each fresh policy forward
    # pass we scan the entire predicted chunk's stop-signal values and find the
    # FIRST index where stop_signal_threshold consecutive values are > 0.5.
    # Freeze fires at THAT index instead of after threshold consecutive ticks,
    # so we don't execute wasted forward motion through the stop region.
    _chunk_stop_index: int | None = None
    _in_chunk_action_idx: int = 0
    if dataset is not None and dataset.fps != fps:
        raise ValueError(f"The dataset fps should be equal to requested fps ({dataset.fps} != {fps}).")

    teleop_arm = teleop_keyboard = None
    if isinstance(teleop, list):
        teleop_keyboard = next((t for t in teleop if isinstance(t, KeyboardTeleop)), None)
        teleop_arm = next(
            (
                t
                for t in teleop
                if isinstance(
                    t,
                    (
                        so_leader.SO100Leader
                        | so_leader.SO101Leader
                        | koch_leader.KochLeader
                        | omx_leader.OmxLeader
                    ),
                )
            ),
            None,
        )

        if not (teleop_arm and teleop_keyboard and len(teleop) == 2 and robot.name == "lekiwi_client"):
            raise ValueError(
                "For multi-teleop, the list must contain exactly one KeyboardTeleop and one arm teleoperator. Currently only supported for LeKiwi robot."
            )

    # Reset policy and processor if they are provided
    if policy is not None and preprocessor is not None and postprocessor is not None:
        policy.reset()
        preprocessor.reset()
        postprocessor.reset()

    # Reset interpolator if provided
    if interpolator is not None:
        interpolator.reset()

    # Calculate control interval based on interpolation
    use_interpolation = interpolator is not None and interpolator.enabled and policy is not None
    control_interval = interpolator.get_control_interval(fps) if interpolator else 1 / fps
    # Pre-compute action key order outside the hot loop — it won't change mid-episode.
    action_keys = sorted(robot.action_features) if use_interpolation else []

    no_action_count = 0
    timestamp = 0
    # Counter for the burst-select feature: increments every loop iteration so
    # we can fire burst capture on a fixed cadence (every n_action_steps ticks).
    loop_iter_idx = 0
    # When the stop signal fires we hold the arms here until the operator presses
    # a new subtask key. Continuously commanding the held pose keeps the servos
    # actively fighting gravity instead of slowly drooping.
    frozen_action: dict | None = None
    # Cached most-recent observation_processed (HWC RGB images + joint state).
    # Refreshed each non-frozen iteration so the planner has fresh frames to
    # look at when the freeze block fires.
    last_obs: dict | None = None
    # Tracks the previously-completed subtask string so we can gate the
    # slots_filled bookkeeping: a slot is only marked filled when skill 3
    # (release) completes RIGHT AFTER a 2a/2b/2c place — otherwise a slipped
    # place followed by a 4-recovery would falsely mark the slot as filled.
    _last_completed_task: str | None = None

    # Per-arm freeze: when a subtask only involves the right arm, hold the left
    # arm at the position it was in when that subtask started (and vice versa).
    # Applied to BOTH the observation handed to the policy (so the model sees a
    # consistent "frozen" state) and the action sent to the robot.
    _LEFT_JOINTS = [
        "left_shoulder_pan.pos", "left_shoulder_lift.pos", "left_elbow_flex.pos",
        "left_wrist_flex.pos",   "left_wrist_roll.pos",    "left_gripper.pos",
    ]
    _RIGHT_JOINTS = [
        "right_shoulder_pan.pos", "right_shoulder_lift.pos", "right_elbow_flex.pos",
        "right_wrist_flex.pos",   "right_wrist_roll.pos",    "right_gripper.pos",
    ]

    def _active_arm_from_task(task_str: str | None) -> str | None:
        """Return 'left', 'right', or None (both/neither) based on task language."""
        if not task_str:
            return None
        t = task_str.lower()
        right = ("right arm" in t) or ("right gripper" in t)
        left = ("left arm" in t) or ("left gripper" in t)
        if right and not left:
            return "right"
        if left and not right:
            return "left"
        return None

    frozen_left_state: dict[str, float] | None = None
    frozen_right_state: dict[str, float] | None = None
    last_active_arm: str | None = None

    # ---- Per-subtask timeout + RA hardcoded-home recovery ----
    # When DYN_TIMEOUT=1, if the current subtask matches DYN_TIMEOUT_KEYS and
    # exceeds DYN_TIMEOUT_S seconds, the right arm is smoothly returned to
    # the home pose (linear interp over DYN_TIMEOUT_HOME_DURATION_S) and a
    # "timeout_recovery_context" is written to events so the next planner
    # call can adjust strategy.
    import os as _os_dyn
    _dyn_timeout_enabled = _os_dyn.environ.get("DYN_TIMEOUT", "0") == "1"
    _DYN_TIMEOUT_S = float(_os_dyn.environ.get("DYN_TIMEOUT_S", "30"))
    _DYN_TIMEOUT_KEYS = set(_os_dyn.environ.get("DYN_TIMEOUT_KEYS", "1,6").split(","))
    # Per-key timeout override: env var DYN_TIMEOUT_S_<key> (e.g. DYN_TIMEOUT_S_5=30)
    # overrides the global _DYN_TIMEOUT_S for that specific subtask. Lets skill 5
    # time out faster (30s) than the precision grabs 1/6 (60s), for example.
    _DYN_TIMEOUT_S_PER_KEY = {
        _k: float(_os_dyn.environ.get(f"DYN_TIMEOUT_S_{_k}", _DYN_TIMEOUT_S))
        for _k in _DYN_TIMEOUT_KEYS
    }
    _DYN_TIMEOUT_HOME_DURATION_S = float(_os_dyn.environ.get("DYN_TIMEOUT_HOME_DURATION_S", "2.0"))
    # Per-subtask stop-signal threshold override: env var STOP_SIGNAL_THRESHOLD_<key>
    # (e.g. STOP_SIGNAL_THRESHOLD_5=3) overrides the global stop_signal_threshold
    # for that subtask in the chunk-lookahead. Lets skill 5 freeze after fewer
    # consecutive stop frames (3) than the others (5).
    _STOP_THRESHOLD_PER_KEY: dict[str, int] = {}
    for _ek, _ev in _os_dyn.environ.items():
        if _ek.startswith("STOP_SIGNAL_THRESHOLD_"):
            try:
                _STOP_THRESHOLD_PER_KEY[_ek[len("STOP_SIGNAL_THRESHOLD_"):]] = int(_ev)
            except ValueError:
                pass
    # Per-subtask "stop early" offset: env var STOP_EARLY_<key> (e.g. STOP_EARLY_5=5)
    # makes that subtask freeze N actions BEFORE the detected stop point (the
    # chunk-lookahead's first consecutive-stop window). Same stop detection, just
    # ends the motion a bit sooner. Clamped so the index never goes below 0.
    _STOP_EARLY_PER_KEY: dict[str, int] = {}
    for _ek, _ev in _os_dyn.environ.items():
        if _ek.startswith("STOP_EARLY_"):
            try:
                _STOP_EARLY_PER_KEY[_ek[len("STOP_EARLY_"):]] = int(_ev)
            except ValueError:
                pass
    # Left-gripper "open a bit more" offset for specific subtasks. During a
    # subtask whose key is in LA_GRIPPER_OPEN_OFFSET_KEYS (default 7 LA release,
    # 9 LA back), LA_GRIPPER_OPEN_OFFSET is ADDED to the left_gripper.pos command
    # sent to the robot so the gripper opens wider (gripper.pos is RANGE_0_100;
    # higher = more open). The offset is a pure PHYSICAL shim: it is removed from
    # the observation BEFORE the policy sees it, so the model keeps operating in
    # the un-offset frame and its behaviour is unaffected. Applies ONLY to the
    # listed subtasks; 0 (default) disables it entirely.
    _LA_GRIPPER_KEY = "left_gripper.pos"
    try:
        _LA_GRIPPER_OFFSET = float(_os_dyn.environ.get("LA_GRIPPER_OPEN_OFFSET", "0") or "0")
    except ValueError:
        _LA_GRIPPER_OFFSET = 0.0
    _LA_GRIPPER_OFFSET_KEYS = {
        _k for _k in _os_dyn.environ.get("LA_GRIPPER_OPEN_OFFSET_KEYS", "7,9").split(",") if _k
    }
    if _LA_GRIPPER_OFFSET != 0.0:
        logging.info(
            "[la-gripper-offset] +%.2f on left_gripper.pos for subtasks %s "
            "(physical only; model sees un-offset state)",
            _LA_GRIPPER_OFFSET, sorted(_LA_GRIPPER_OFFSET_KEYS),
        )
    _RA_JOINTS = [
        "right_shoulder_pan.pos", "right_shoulder_lift.pos", "right_elbow_flex.pos",
        "right_wrist_flex.pos",   "right_wrist_roll.pos",    "right_gripper.pos",
    ]
    # Load RA home pose from the home_pose_file (if present in the kwargs).
    _ra_home_pose: dict[str, float] = {}
    _hpf = home_pose_file
    if not _ra_home_pose:
        # Standard path used by every recording script in this project.
        for _candidate in (
            _hpf or "",
        ):
            try:
                with open(_candidate) as _hf:
                    for _line in _hf:
                        _line = _line.strip()
                        if "=" in _line:
                            _k, _v = _line.split("=", 1)
                            if _k.strip() in _RA_JOINTS:
                                _ra_home_pose[_k.strip()] = float(_v.strip())
                if _ra_home_pose:
                    break
            except FileNotFoundError:
                continue
    if _dyn_timeout_enabled and policy is not None:
        if _ra_home_pose:
            logging.info(
                "[dyn-timeout] enabled — keys=%s timeout=%.1fs RA-home=%.1fs",
                sorted(_DYN_TIMEOUT_KEYS), _DYN_TIMEOUT_S, _DYN_TIMEOUT_HOME_DURATION_S,
            )
        else:
            logging.warning("[dyn-timeout] enabled but RA home pose not found; recovery disabled")
            _dyn_timeout_enabled = False
    _timeout_subtask_start: dict[str, float] = {}  # subtask_key -> start time
    _timeout_last_key: str | None = None
    _ra_recovery: dict | None = None  # {start_pos, target_pos, start_t}
    # Inspection state: set when timeout fires; cleared when Gemini's decision
    # is acted on. Holds the snapshots needed to either resume the subtask
    # (extend) or fall back to the hardcoded RA-home recovery on "4".
    _inspection_state: dict | None = None
    _consecutive_timeouts: dict[str, int] = {}  # subtask_key -> consecutive timeout count
    _DYN_TIMEOUT_RETRY_LIMIT = int(_os_dyn.environ.get("DYN_TIMEOUT_RETRY_LIMIT", "5"))
    # Sub-frame multiplier used by the interpolator only on chunk boundaries
    # (when the policy generates a new chunk and action[0] may differ from the
    # previous chunk's last action). Larger = smoother boundary transition.
    # Defaults to 3x the within-chunk multiplier so visible jumps stretch.
    _BOUNDARY_INTERP_MULTIPLIER = int(
        _os_dyn.environ.get(
            "BOUNDARY_INTERP_MULTIPLIER",
            str((interpolator.multiplier * 3) if (interpolator is not None and hasattr(interpolator, "multiplier")) else 9),
        )
    )
    # Long-pause smoothing: when the robot has been frozen for > N seconds
    # (typically because the high-level planner — Gemini/Claude — took several
    # seconds to decide the next subtask), the first action of the next chunk
    # may target a pose noticeably distant from the held freeze pose. This
    # produces a visible "burst" at the boundary. After a long freeze we apply
    # an extra-large boundary multiplier for the first action only, then revert
    # to the normal _BOUNDARY_INTERP_MULTIPLIER for the rest of the chunk.
    _LONG_PAUSE_THRESHOLD_S = float(_os_dyn.environ.get("LONG_PAUSE_THRESHOLD_S", "1.5"))
    _LONG_PAUSE_BOUNDARY_MULT = int(
        _os_dyn.environ.get(
            "LONG_PAUSE_BOUNDARY_MULT",
            str(_BOUNDARY_INTERP_MULTIPLIER * 3),
        )
    )
    _freeze_started_t: float | None = None
    _long_pause_boundary_active: bool = False
    _BOUNDARY_GAP_LOG = _os_dyn.environ.get("BOUNDARY_GAP_LOG", "1") == "1"
    # Tracks the previous loop iteration's current_task so we can flush stale
    # policy/interpolator state on the None->non-None transition.
    _last_current_task_for_reset: str | None = None

    # ---- Dynamic chunk size for specific subtasks (env-var gated) ----
    # When DYN_CHUNK=1, the policy's n_action_steps decays from DYN_CHUNK_MAX to
    # DYN_CHUNK_MIN across policy calls while the current subtask matches one
    # of DYN_CHUNK_KEYS. The decay step DYN_CHUNK_STEP is applied every
    # DYN_CHUNK_CALLS_PER_STEP-th call. Useful for tasks requiring increasing
    # precision near the end (e.g. RA grab blue).
    _dyn_chunk_enabled = _os_dyn.environ.get("DYN_CHUNK", "0") == "1"
    _DYN_CHUNK_MAX  = int(_os_dyn.environ.get("DYN_CHUNK_MAX",  "30"))
    _DYN_CHUNK_MIN  = int(_os_dyn.environ.get("DYN_CHUNK_MIN",  "10"))
    _DYN_CHUNK_STEP = int(_os_dyn.environ.get("DYN_CHUNK_STEP", "1"))
    _DYN_CHUNK_CALLS_PER_STEP = max(1, int(_os_dyn.environ.get("DYN_CHUNK_CALLS_PER_STEP", "1")))
    _DYN_CHUNK_KEYS = set(_os_dyn.environ.get("DYN_CHUNK_KEYS", "1,6").split(","))
    # When 1, the FIRST chunk of each subtask starts at MIN (a small careful
    # initial move), then the decay+wrap takes it to MAX and back down:
    # e.g. 5 -> 30 -> 25 -> 20 -> 15 -> 10 -> 5 -> 30 -> ...  When 0 (default),
    # the first chunk starts at MAX (30 -> 25 -> ... -> 5 -> 30 -> ...).
    _DYN_CHUNK_START_MIN = _os_dyn.environ.get("DYN_CHUNK_START_MIN", "0") == "1"
    _dyn_chunk_state = {
        "current": None,         # n to apply on the next forward pass
        "executing": None,       # size of the currently-executing chunk
        "calls_in_chunk": 0,     # how many actions popped from the current chunk
        "chunks_completed": 0,   # full chunks completed since subtask start
        "last_subtask": None,
        "orig_n": None,
    }

    def _subtask_key_from_task(task_str):
        """Map a subtask instruction string back to its numeric key.

        Used by every per-subtask feature (dyn-chunk, dyn-timeout, per-key stop
        threshold, stop-early offset). Must cover ALL subtasks the keymap /
        planner can emit — a key that resolves to None gets only global
        defaults, so a missing entry silently disables per-key behaviour for
        that subtask. Returns None only for non-policy tasks (e.g. ra_home,
        which is intercepted separately).
        """
        if not task_str:
            return None
        t = task_str.lower()
        # --- grabs ---
        if "grasp the nearest blue thread" in t and "green tray" in t:
            return "1"
        if "grasp the exposed blue thread" in t:
            return "6"
        if "grasp the white edge" in t:
            return "5"
        # --- places (slot number distinguishes 2a/2b/2c) ---
        if "into slot 1" in t:
            return "2a"
        if "into slot 2" in t:
            return "2b"
        if "into slot 3" in t:
            return "2c"
        # --- releases / returns ---
        # ORDER MATTERS: subtask 8 ("release the white edge and return the
        # left arm to rest position") contains the marker substrings of both
        # 7 ("release the white edge ...") and 9 ("return the left arm to
        # rest"), so it MUST be matched before them.
        if "release the white edge and return" in t:
            return "8"
        if "release the white edge by opening" in t:
            return "7"
        if "release the gauze by opening" in t:
            return "3"
        if "return the right arm to rest" in t:
            return "4"
        if "return the left arm to rest" in t:
            return "9"
        return None

    if _dyn_chunk_enabled and policy is not None:
        logging.info(
            "[dyn-chunk] enabled — keys=%s max=%d min=%d step=%d every %d calls",
            sorted(_DYN_CHUNK_KEYS), _DYN_CHUNK_MAX, _DYN_CHUNK_MIN, _DYN_CHUNK_STEP,
            _DYN_CHUNK_CALLS_PER_STEP,
        )

    start_episode_t = time.perf_counter()
    while timestamp < control_time_s:
        start_loop_t = time.perf_counter()
        policy_action_tensor = None  # populated below if policy ran this iteration

        if events["exit_early"]:
            events["exit_early"] = False
            break

        # If we're in a stop-signal freeze, keep commanding the held pose every
        # frame so the servos resist gravity. Any subtask key press
        # (events["current_task"] becomes non-None) ends the freeze.
        if frozen_action is not None:
            if events.get("current_task") is not None:
                # Two interception paths on freeze exit:
                #  (1) ra_home (hardcoded smooth RA return) — always overrides
                #      the policy with a linear lerp; LA held at snapshot.
                #      Fires regardless of inspection mode (Gemini pick OR
                #      operator manual trigger).
                #  (2) inspection-mode bookkeeping — reset the consecutive-
                #      timeout counter when Gemini's resolution differs from
                #      the timed-out subtask (strategy switch).
                _ct = events.get("current_task") or ""
                _is_ra_home = "right arm hardcoded recovery to home" in _ct
                if _is_ra_home:
                    logging.info("[ra_home] triggering hardcoded RA recovery")
                    if _inspection_state is not None:
                        _start_ra_pose = _inspection_state["start_ra"]
                        _la_hold_pose = _inspection_state["la_snapshot"]
                        _timed_out_key = _inspection_state.get("subtask")
                        # ra_home counts as a strategy change away from the
                        # timed-out subtask — reset its streak so future retries
                        # judge purely on the post-recovery scene.
                        if _timed_out_key in _consecutive_timeouts:
                            _consecutive_timeouts[_timed_out_key] = 0
                        _inspection_state = None
                    else:
                        # Manual / non-inspection trigger — snapshot LA + RA
                        # from the most recent observation so the recovery
                        # holds LA wherever it was when ra_home was selected.
                        _start_ra_pose = {
                            k: float(last_obs[k]) for k in _RA_JOINTS
                            if last_obs is not None and k in last_obs
                        }
                        _la_hold_pose = {
                            k: float(last_obs[k]) for k in _LEFT_JOINTS
                            if last_obs is not None and k in last_obs
                        }
                    _ra_recovery = {
                        "start_pos": _start_ra_pose,
                        "target_pos": dict(_ra_home_pose),
                        "la_hold": _la_hold_pose,
                        "start_t": time.perf_counter(),
                    }
                    # Clear current_task so the policy doesn't run anything —
                    # recovery handles motion directly.
                    events["current_task"] = None
                elif _inspection_state is not None:
                    _timed_out_key = _inspection_state.get("subtask")
                    _resolved_key = _subtask_key_from_task(_ct)
                    # If the planner is switching to a DIFFERENT subtask
                    # (strategy change), reset the consecutive-timeout
                    # counter for the timed-out subtask so a future retry
                    # of the original subtask starts fresh based on new
                    # visuals — not as a continuation of the prior streak.
                    if _resolved_key != _timed_out_key and _timed_out_key in _consecutive_timeouts:
                        logging.info(
                            f"[timeout-inspection] strategy change "
                            f"({_timed_out_key} → {_resolved_key}); "
                            f"resetting consecutive_timeouts[{_timed_out_key}]"
                        )
                        _consecutive_timeouts[_timed_out_key] = 0
                    # Any non-ra_home resolution (extend with 1/6, release
                    # with 4/8, etc.) — let the normal subtask flow execute
                    # via policy.
                    _inspection_state = None
                frozen_action = None
                if policy is not None:
                    policy.reset()
            else:
                # While frozen and waiting for the next subtask, give the
                # high-level planner a chance to pick one. The planner has its
                # own cooldown and is a no-op if it was just called or if the
                # operator already set events["current_task"]. Safe because the
                # robot is physically still here.
                #
                # IMPORTANT: refresh the observation FIRST so the planner sees
                # the CURRENT camera view, not the stale frame from when the
                # previous subtask ended. The cameras run async, so read_latest
                # returns the live frame; the freeze loop otherwise never
                # re-reads obs (it `continue`s below), which previously made
                # Gemini decide on an out-of-date scene.
                if planner is not None:
                    try:
                        _fresh_obs = robot.get_observation()
                        last_obs = robot_observation_processor(_fresh_obs)
                    except Exception as _e:
                        logging.warning(f"[freeze] obs refresh for planner failed: {_e}")
                    if last_obs is not None:
                        try:
                            planner.maybe_call(events, last_obs, single_task or "")
                        except Exception as e:
                            logging.warning(f"Planner call raised: {e}")
                robot.send_action(frozen_action)
                if display_data:
                    try:
                        import rerun as rr
                        rr.log("stop_signal/state", rr.TextLog("FROZEN — press 1-9 to resume"))
                    except Exception:
                        pass
                # CRITICAL: mark that we are in the frozen/waiting state so the
                # NEXT subtask (set by Gemini/operator) is detected as a fresh
                # None->non-None transition at the line ~1027 reset block. The
                # `continue` below skips that block, so without this the
                # `_last_current_task_for_reset` would keep the OLD subtask
                # name through the whole freeze — making the transition reset
                # (interpolator re-prime + long-pause smoothing) NOT fire, and
                # the policy would burst through a chunk interpolated from a
                # stale prev pose.
                _last_current_task_for_reset = None
                precise_sleep(1 / fps - (time.perf_counter() - start_loop_t))
                timestamp = time.perf_counter() - start_episode_t
                continue

        # Get robot observation. Default path: single read.
        # Burst-select path (gated by burst_select_n>0): on policy-tick boundaries
        # (every n_action_steps loop iterations), grab N reads, keep the sharpest
        # frame per camera. Non-policy-tick reads use the standard single read.
        if (
            burst_select_n > 0
            and policy is not None
            and (loop_iter_idx % max(int(getattr(policy.config, "n_action_steps", 1)), 1)) == 0
        ):
            from lerobot.utils.burst_camera import burst_capture_and_select
            _img_keys = [k for k in policy.config.input_features if "images." in k]
            try:
                obs = burst_capture_and_select(robot, _img_keys, burst_select_n)
            except Exception as _e:
                logging.warning(
                    f"[obs] burst_capture_and_select raised ({_e}); "
                    f"falling back to last_obs (camera recovery in progress)."
                )
                obs = last_obs if last_obs is not None else robot.get_observation()
        else:
            try:
                obs = robot.get_observation()
            except Exception as _e:
                # Camera transient failure (e.g. USB hiccup during arm motion):
                # use the last good observation rather than crashing. The
                # camera's background thread keeps trying to reconnect — once
                # it succeeds, fresh frames will flow on the next iteration.
                logging.warning(
                    f"[obs] robot.get_observation() raised ({type(_e).__name__}: {_e}); "
                    f"falling back to last_obs (camera recovery in progress)."
                )
                if last_obs is not None:
                    obs = last_obs
                else:
                    # No previous obs to fall back to (very early in the run).
                    # Sleep briefly and retry once; if still failing, re-raise.
                    time.sleep(0.2)
                    obs = robot.get_observation()
        loop_iter_idx += 1

        # Left-gripper offset compensation (subtasks 7/9): if we are adding a
        # physical open-offset to the gripper COMMAND (see the send block), undo
        # it on the way IN so the policy never sees the offset. Done on the raw
        # obs at the source so every downstream consumer (policy input,
        # interpolator prime, dataset frame) stays in the un-offset frame.
        if (
            _LA_GRIPPER_OFFSET != 0.0
            and _subtask_key_from_task(events.get("current_task")) in _LA_GRIPPER_OFFSET_KEYS
            and isinstance(obs, dict)
            and _LA_GRIPPER_KEY in obs
        ):
            try:
                obs[_LA_GRIPPER_KEY] = max(0.0, float(obs[_LA_GRIPPER_KEY]) - _LA_GRIPPER_OFFSET)
            except (TypeError, ValueError):
                pass

        # Applies a pipeline to the raw robot observation, default is IdentityProcessor
        obs_processed = robot_observation_processor(obs)

        # Cache the most recent observation so the planner (which only fires
        # inside the freeze block, where obs is not re-fetched) has fresh
        # frames to inspect when the next stop signal triggers.
        last_obs = obs_processed

        # ---- RA hardcoded-home recovery in progress (from a timeout) ----
        # Smoothly interpolate the right arm from its captured start pose to
        # the home pose over _DYN_TIMEOUT_HOME_DURATION_S; left arm held at
        # current position. While recovering, skip the policy entirely and
        # the next planner call gets the timeout context in its prompt.
        if _ra_recovery is not None:
            _rec_t = time.perf_counter() - _ra_recovery["start_t"]
            _rec_alpha = min(1.0, _rec_t / max(_DYN_TIMEOUT_HOME_DURATION_S, 1e-6))
            _ra_action = {
                k: (_ra_recovery["start_pos"][k]
                    + _rec_alpha * (_ra_recovery["target_pos"][k] - _ra_recovery["start_pos"][k]))
                for k in _RA_JOINTS if k in _ra_recovery["target_pos"]
            }
            # Use the LA snapshot captured at timeout time, NOT the current
            # obs — otherwise gravity-induced droop accumulates over iters.
            _la_hold = dict(_ra_recovery["la_hold"])
            _recovery_action = {**_la_hold, **_ra_action}
            try:
                robot.send_action(_recovery_action)
            except Exception as e:
                logging.warning(f"[dyn-timeout] send_action during recovery raised: {e}")
            if _rec_alpha >= 1.0:
                logging.info("[dyn-timeout] RA back at home; recovery complete — freezing for next planner pick")
                _ra_recovery = None
                # CRITICAL: freeze the robot at the recovered pose (RA home +
                # LA held) and WAIT for the planner to pick the next subtask.
                # Without this, frozen_action is None so the robot is "live" —
                # if the planner is still on cooldown when the loop reaches the
                # policy block, the policy runs on the umbrella/fallback task
                # and yanks RA to a garbage pose (e.g. the failed-6 position).
                # Setting frozen_action holds the arm home until current_task
                # is set, then the normal transition (interpolator re-prime +
                # long-pause smoothing) takes over.
                frozen_action = dict(_recovery_action)
                _freeze_started_t = time.perf_counter()
                if policy is not None and hasattr(policy, "reset"):
                    try: policy.reset()
                    except Exception: pass
                # CRITICAL: the RA just moved to home via the HARDCODED path,
                # bypassing the per-arm freeze. Any frozen_right_state snapshot
                # still points at the PRE-recovery pose (e.g. the skill-6 stop
                # position). The per-arm freeze only re-snapshots when
                # active_arm CHANGES, so if the next subtask is another LA skill
                # (e.g. 6→7→9→ra_home→5, all "left"), it would NOT re-snapshot
                # and the stale hold would yank the RA back to the skill-6 pose.
                # Invalidate the snapshots + force last_active_arm=None so the
                # next subtask re-snapshots the inactive arm from the home pose.
                frozen_left_state = None
                frozen_right_state = None
                last_active_arm = None
            precise_sleep(1 / fps - (time.perf_counter() - start_loop_t))
            timestamp = time.perf_counter() - start_episode_t
            continue

        # ---- Timeout detection for precision-grab subtasks (1, 6) ----
        if _dyn_timeout_enabled and policy is not None:
            _cur_to_key = _subtask_key_from_task(events.get("current_task"))
            if _cur_to_key in _DYN_TIMEOUT_KEYS:
                if _cur_to_key != _timeout_last_key:
                    _timeout_subtask_start[_cur_to_key] = time.perf_counter()
                    _timeout_last_key = _cur_to_key
                else:
                    _elapsed = time.perf_counter() - _timeout_subtask_start.get(_cur_to_key, time.perf_counter())
                    _to_limit = _DYN_TIMEOUT_S_PER_KEY.get(_cur_to_key, _DYN_TIMEOUT_S)
                    if _elapsed > _to_limit:
                        logging.warning(
                            f"[dyn-timeout] subtask {_cur_to_key} exceeded {_to_limit:.1f}s "
                            f"(elapsed {_elapsed:.1f}s); returning RA to home"
                        )
                        try:
                            from lerobot.utils.utils import log_say as _log_say
                            _log_say(f"timeout, right arm returning home", play_sounds=True)
                        except Exception:
                            pass
                        # Capture BOTH arms at timeout time. The arms stay
                        # frozen at these positions while the planner inspects
                        # the grippers and decides what to do (extend, drop,
                        # release, etc.). The RA snapshot is also stored so we
                        # can trigger the hardcoded smooth-home recovery later
                        # if the planner picks "4".
                        _start_ra = {
                            k: float(obs[k]) for k in _RA_JOINTS if k in obs
                        }
                        _la_snapshot = {
                            k: float(obs[k]) for k in _LEFT_JOINTS if k in obs
                        }
                        # Freeze both arms via the existing frozen_action
                        # mechanism (sends the held pose every iter).
                        frozen_action = {**_la_snapshot, **_start_ra}
                        # Track when this freeze began so the next transition
                        # can detect a long planner-induced pause and apply
                        # extra-aggressive boundary smoothing on the next chunk.
                        if _freeze_started_t is None:
                            _freeze_started_t = time.perf_counter()
                        _consecutive_timeouts[_cur_to_key] = _consecutive_timeouts.get(_cur_to_key, 0) + 1
                        # Reset the dyn-chunk state for this subtask so that
                        # any retry (including by the same key) begins again
                        # at DYN_CHUNK_MAX rather than at the floor.
                        if _dyn_chunk_state.get("last_subtask") == _cur_to_key:
                            _dyn_chunk_state["last_subtask"] = None
                            _dyn_chunk_state["current"] = None
                            _dyn_chunk_state["executing"] = None
                            _dyn_chunk_state["calls_in_chunk"] = 0
                        # Inspection state — used to:
                        #  (a) keep arms frozen via frozen_action above
                        #  (b) trigger hardcoded RA recovery if planner picks "4"
                        _inspection_state = {
                            "subtask": _cur_to_key,
                            "start_ra": _start_ra,
                            "la_snapshot": _la_snapshot,
                            "is_strategy_b": _cur_to_key == "6",
                        }
                        # Tell the planner: this is an INSPECTION request, not
                        # a regular post-recovery prompt. The planner reads
                        # this flag and formats a different prompt.
                        events["timeout_inspection_pending"] = {
                            "subtask": _cur_to_key,
                            "elapsed_s": round(_elapsed, 1),
                            "timeout_s": _DYN_TIMEOUT_S,
                            "consecutive_timeouts": _consecutive_timeouts[_cur_to_key],
                            "retry_limit": _DYN_TIMEOUT_RETRY_LIMIT,
                            "is_strategy_b": _cur_to_key == "6",
                        }
                        # Clear current_task so the planner fires next iteration
                        events["current_task"] = None
                        _timeout_subtask_start.pop(_cur_to_key, None)
                        _timeout_last_key = None
                        # Skip rest of this iter; recovery block handles next iters.
                        precise_sleep(1 / fps - (time.perf_counter() - start_loop_t))
                        timestamp = time.perf_counter() - start_episode_t
                        continue
            else:
                _timeout_last_key = None

        # Bootstrap: if there's no current subtask and the robot isn't frozen
        # (e.g. at episode start), give the planner a chance to pick the first
        # one. maybe_call() has its own cooldown so it won't spam.
        if (
            planner is not None
            and frozen_action is None
            and events.get("current_task") is None
        ):
            try:
                planner.maybe_call(events, last_obs, single_task or "")
            except Exception as e:
                logging.warning(f"Planner call raised: {e}")

        # Detect a fresh subtask start (current_task transitions from None to a
        # non-None value, e.g. via SPACE-confirm, 1-9 keypress, or planner pick)
        # and flush the policy + interpolator. Without this, any actions the
        # policy generated against the fallback umbrella task while we were
        # waiting (e.g. during a pending-Gemini-decision pause) would still be
        # buffered in the interpolator and dispense as a burst when the new
        # subtask takes effect.
        _cur_task_now = events.get("current_task")
        if _cur_task_now != _last_current_task_for_reset:
            if policy is not None and hasattr(policy, "reset"):
                policy.reset()
            for _processor in (preprocessor, postprocessor):
                if _processor is not None:
                    _processor.reset()
            stop_count = 0
            _chunk_stop_index = None
            _in_chunk_action_idx = 0
            _dyn_chunk_state["last_subtask"] = None
            _dyn_chunk_state["executing"] = None
            _dyn_chunk_state["calls_in_chunk"] = 0
            frozen_left_state = None
            frozen_right_state = None
            last_active_arm = None
            if interpolator is not None:
                try:
                    # Prime _prev with current robot pose so the next add()
                    # smoothly interpolates from "where we are now" to the
                    # new chunk's action[0], avoiding the no-interp jump.
                    if action_keys:
                        _curpose = torch.tensor([float(obs.get(k, 0.0)) for k in action_keys])
                        interpolator.reset(prev=_curpose)
                    else:
                        interpolator.reset()
                except Exception: pass
            # Long-pause detection: if the freeze leading into this transition
            # exceeded LONG_PAUSE_THRESHOLD_S (typically because Gemini/Claude
            # took multiple seconds to pick the next subtask), arm the
            # extended-multiplier flag so this chunk's first action gets
            # extra-aggressive smoothing.
            _freeze_dur = None
            if _freeze_started_t is not None:
                _freeze_dur = time.perf_counter() - _freeze_started_t
                _freeze_started_t = None
                if _freeze_dur > _LONG_PAUSE_THRESHOLD_S:
                    _long_pause_boundary_active = True
                    logging.info(
                        f"[long-pause] freeze was {_freeze_dur:.1f}s (> {_LONG_PAUSE_THRESHOLD_S}s) "
                        f"-> next chunk's first action will use multiplier={_LONG_PAUSE_BOUNDARY_MULT} "
                        f"(vs normal boundary {_BOUNDARY_INTERP_MULTIPLIER})"
                    )
            logging.info(
                f"[transition] new subtask='{str(_cur_task_now)[:60]}...' freeze_dur="
                f"{('%.2fs' % _freeze_dur) if _freeze_dur is not None else 'n/a'} "
                f"-> flushed policy + interpolator (primed with current pose)"
            )
        _last_current_task_for_reset = _cur_task_now

        # ---- Per-arm freeze: snapshot inactive arm at task transition ----
        # Only meaningful during inference (policy != None) and when a specific
        # subtask is selected.
        if policy is not None:
            current_task_str = events.get("current_task")
            active_arm = _active_arm_from_task(current_task_str)
            if active_arm != last_active_arm:
                if active_arm == "right":
                    # Right arm operates → freeze left arm at current position
                    frozen_left_state = {
                        k: float(obs[k]) for k in _LEFT_JOINTS if k in obs
                    }
                    frozen_right_state = None
                elif active_arm == "left":
                    # Left arm operates → freeze right arm
                    frozen_right_state = {
                        k: float(obs[k]) for k in _RIGHT_JOINTS if k in obs
                    }
                    frozen_left_state = None
                else:
                    # Bimanual or no specific task → release both freezes
                    frozen_left_state = None
                    frozen_right_state = None
                last_active_arm = active_arm

            # Apply state freeze to the observation handed to the policy.
            if frozen_left_state:
                for k, v in frozen_left_state.items():
                    if k in obs_processed:
                        obs_processed[k] = v
            if frozen_right_state:
                for k, v in frozen_right_state.items():
                    if k in obs_processed:
                        obs_processed[k] = v

        # ---- Confidence guard for skill 1 (RA grab blue thread) ----
        # Pi0.5 will silently grasp the white part of the gauze when blue isn't
        # accessible. Refuse skill 1 if the planner's last vision call scored
        # blue-visibility below threshold. Triggered guard nulls the current
        # task and falls into the existing idle-hold path so the operator can
        # pick a safer skill (typically 5: LA lift white edge).
        if (
            planner is not None
            and _skill_1_label is not None
            and blue_confidence_threshold > 0.0
            and events.get("current_task") == _skill_1_label
        ):
            _conf = planner.last_blue_confidence()
            if _conf is not None and _conf < blue_confidence_threshold:
                logging.warning(
                    "Confidence guard: refusing skill 1 (RA grab blue) — "
                    f"planner blue_conf={_conf:.2f} < threshold={blue_confidence_threshold}. "
                    "Suggest pressing 5 (LA lift white edge) instead."
                )
                try:
                    log_say("low blue confidence", play_sounds=True)
                except Exception:
                    pass
                events["current_task"] = None

        if policy is not None or dataset is not None:
            observation_frame = build_dataset_frame(dataset.features, obs_processed, prefix=OBS_STR)

            # Single-cam-per-subtask masking: zero non-active cameras based on
            # the current subtask string. Active-cam map is in SUBTASK_ACTIVE_CAM.
            # NOTE: must NOT mutate in place — observation_frame's image arrays
            # share memory with obs_processed (and thus last_obs), and the
            # high-level planner (Gemini/Claude) reads last_obs for vision. The
            # mask is intended for the *low-level policy only*, not for the
            # planner. Replace the array with a freshly-zeroed copy so the
            # planner still sees the real frames.
            if cam_mask_per_subtask and policy is not None:
                _task_str = events.get("current_task") or single_task or ""
                _active_cam = None
                for _frag, _cam in SUBTASK_ACTIVE_CAM.items():
                    if _frag in _task_str:
                        _active_cam = _cam
                        break
                if _active_cam is not None:
                    _active_key = f"{OBS_STR}.images.{_active_cam}"
                    for _k in list(observation_frame.keys()):
                        if _k.startswith(f"{OBS_STR}.images.") and _k != _active_key:
                            _val = observation_frame[_k]
                            if hasattr(_val, "clone"):  # torch.Tensor
                                observation_frame[_k] = _val.new_zeros(_val.shape)
                            else:  # numpy ndarray
                                import numpy as _np_mask
                                observation_frame[_k] = _np_mask.zeros_like(_val)

            # Optional: log the post-mask, post-burst-select frames the policy
            # actually receives. Shown under "policy_input/*" in Rerun so it
            # sits alongside the raw "observation/*" feed without colliding.
            if display_data and policy is not None:
                try:
                    import rerun as rr
                    for _k, _v in observation_frame.items():
                        if not _k.startswith(f"{OBS_STR}.images."):
                            continue
                        _arr = _v
                        if isinstance(_arr, np.ndarray):
                            if _arr.ndim == 3 and _arr.shape[0] in (1, 3, 4) and _arr.shape[-1] not in (1, 3, 4):
                                _arr = np.transpose(_arr, (1, 2, 0))
                            _short = _k.split(".")[-1]
                            rr.log(f"policy_input/{_short}", rr.Image(_arr))
                except Exception:
                    pass

        # Track whether this iteration should be recorded to the dataset.
        # Interpolated-only iterations send actions to the robot but don't record frames,
        # keeping the dataset at the original fps while the robot moves at the higher rate.
        is_record_frame = True

        # Get action from either policy or teleop
        # When subtasks are enabled, hold still until the operator presses a subtask key.
        # Also hold still on 'e' (subtask finished) and '0' (drop).
        # Send current position back to keep motors alive (avoid connection timeout).
        current_task = events.get("current_task")
        _idle_hold = (enable_subtasks
                      and policy is not None and preprocessor is not None and postprocessor is not None
                      and "current_task" in events
                      and (not current_task or current_task in ("subtask finished", "drop that subtask")))
        if _idle_hold:
            hold_action = {k: v for k, v in obs_processed.items() if ".pos" in k}
            if hold_action:
                robot.send_action(hold_action)
            precise_sleep(1 / fps - (time.perf_counter() - start_loop_t))
            continue
        if policy is not None and preprocessor is not None and postprocessor is not None:
            # Build the observation handed to the policy. Optionally rename
            # image keys for openpi-style checkpoints; original observation_frame
            # keeps the bi_so_follower keys for the dataset writer.
            if image_keys_openpi_style:
                _policy_obs = {
                    BI_SO_TO_OPENPI_KEYS.get(_k, _k): _v for _k, _v in observation_frame.items()
                }
            else:
                _policy_obs = observation_frame

            # With interpolation: only call policy when interpolator needs new action
            if use_interpolation:
                ran_inference = False

                if interpolator.needs_new_action():
                    # Detect if this predict_action call will trigger a fresh
                    # forward pass (chunk boundary). Pi0.5's select_action runs
                    # a new forward pass when its internal _action_queue is
                    # empty. If we're at a boundary, the new chunk's action[0]
                    # is generated from the latest observation and may differ
                    # noticeably from the end of the previous chunk — so we
                    # interpolate over MORE sub-frames on the boundary add()
                    # call to smooth the visible motion.
                    _at_chunk_boundary = False
                    try:
                        _q = getattr(policy, "_action_queue", None)
                        if _q is not None and len(_q) == 0:
                            _at_chunk_boundary = True
                    except Exception:
                        pass
                    # Dynamic chunk size hook (per-chunk reduction).
                    # Each predict_action call below pops one action from the
                    # policy's internal queue. The policy only does a NEW
                    # forward pass (and reads n_action_steps) when its queue
                    # is empty — so we set n_action_steps just before the call
                    # that will trigger a fresh chunk fetch, then count action
                    # pops until that chunk is done. When the count reaches
                    # the chunk size, the NEXT call will trigger another
                    # forward pass — that's when we shrink the size by
                    # DYN_CHUNK_STEP (floored at DYN_CHUNK_MIN).
                    if _dyn_chunk_enabled and policy is not None:
                        _cur_key = _subtask_key_from_task(events.get("current_task"))
                        if _cur_key in _DYN_CHUNK_KEYS:
                            if _cur_key != _dyn_chunk_state["last_subtask"]:
                                # New subtask: reset. Start at MIN if
                                # DYN_CHUNK_START_MIN (small careful first move,
                                # then decay+wrap takes it 5 -> 30 -> 25 -> ...),
                                # otherwise start at MAX (the default).
                                _dyn_chunk_state["current"] = (
                                    _DYN_CHUNK_MIN if _DYN_CHUNK_START_MIN else _DYN_CHUNK_MAX
                                )
                                _dyn_chunk_state["executing"] = None
                                _dyn_chunk_state["calls_in_chunk"] = 0
                                _dyn_chunk_state["chunks_completed"] = 0
                                _dyn_chunk_state["last_subtask"] = _cur_key
                                if _dyn_chunk_state["orig_n"] is None:
                                    _dyn_chunk_state["orig_n"] = policy.config.n_action_steps
                            _exec = _dyn_chunk_state["executing"]
                            _calls = _dyn_chunk_state["calls_in_chunk"]
                            if _exec is None or _calls >= _exec:
                                # This call triggers a NEW forward pass — apply
                                # the current target chunk size, then bump the
                                # completed-chunks counter. Reduce only every
                                # DYN_CHUNK_CALLS_PER_STEP-th completed chunk
                                # (so e.g. step=1, calls_per_step=2 → drops by
                                # 1 every 2 finished chunks).
                                policy.config.n_action_steps = _dyn_chunk_state["current"]
                                _dyn_chunk_state["executing"] = _dyn_chunk_state["current"]
                                _dyn_chunk_state["calls_in_chunk"] = 1
                                _dyn_chunk_state["chunks_completed"] += 1
                                if _dyn_chunk_state["chunks_completed"] % _DYN_CHUNK_CALLS_PER_STEP == 0:
                                    _next = _dyn_chunk_state["current"] - _DYN_CHUNK_STEP
                                    # Wrap-around: if decrementing would drop
                                    # below MIN, bounce back to MAX and start
                                    # the cycle over (instead of clamping at
                                    # MIN forever).
                                    if _next < _DYN_CHUNK_MIN:
                                        _next = _DYN_CHUNK_MAX
                                else:
                                    _next = _dyn_chunk_state["current"]
                                logging.info(
                                    f"[dyn-chunk] subtask {_cur_key} chunk #{_dyn_chunk_state['chunks_completed']}: "
                                    f"n_action_steps={_dyn_chunk_state['current']} "
                                    f"(next chunk will be {_next})"
                                )
                                _dyn_chunk_state["current"] = _next
                            else:
                                # Still popping from the in-flight chunk; no change.
                                _dyn_chunk_state["calls_in_chunk"] += 1
                        else:
                            if _dyn_chunk_state["orig_n"] is not None and _dyn_chunk_state["last_subtask"] is not None:
                                policy.config.n_action_steps = _dyn_chunk_state["orig_n"]
                            _dyn_chunk_state["last_subtask"] = None
                            _dyn_chunk_state["current"] = None
                            _dyn_chunk_state["executing"] = None
                            _dyn_chunk_state["calls_in_chunk"] = 0
                    action_values = predict_action(
                        observation=_policy_obs,
                        policy=policy,
                        device=get_safe_torch_device(policy.config.device),
                        preprocessor=preprocessor,
                        postprocessor=postprocessor,
                        use_amp=policy.config.use_amp,
                        # Prefer the live subtask set via keys 1-9/2+a-c (or 'e');
                        # fall back to the umbrella task when nothing is pressed.
                        task=events.get("current_task") or single_task,
                        robot_type=robot.robot_type,
                    )
                    # Capture the raw policy tensor BEFORE it's flattened into a
                    # 12-key motor dict — the stop-signal check below reads
                    # action[stop_signal_dim] from this tensor. Without this
                    # capture, interpolation runs forever and the robot never
                    # freezes when the policy says the subtask is done.
                    policy_action_tensor = action_values
                    act_processed_policy = make_robot_action(action_values, dataset.features)
                    robot_action_to_send = robot_action_processor((act_processed_policy, obs))

                    # ---- Stop-signal chunk lookahead ----
                    # After each fresh policy forward pass, scan the full chunk
                    # (just-popped action + remaining queue) for the FIRST
                    # window of stop_signal_threshold consecutive values > 0.5.
                    # Freeze fires at the START of that window, so we don't
                    # execute wasted motion through the stop region.
                    if (
                        stop_signal_dim is not None
                        and policy_action_tensor is not None
                    ):
                        if _at_chunk_boundary:
                            _chunk_stops: list[float] = []
                            try:
                                _t0 = policy_action_tensor.detach().squeeze(0).flatten()
                                if _t0.numel() > stop_signal_dim:
                                    _chunk_stops.append(float(_t0[stop_signal_dim]))
                            except Exception:
                                pass
                            try:
                                _queue = getattr(policy, "_action_queue", None)
                                if _queue is not None:
                                    for _a in list(_queue):
                                        try:
                                            # Queued actions are normalized; the popped
                                            # action has already passed postprocessing.
                                            # Compare every stop in the same physical
                                            # [0, 1] target space.
                                            _decoded = postprocessor(_a.clone())
                                            _ta = _decoded.detach().squeeze(0).flatten()
                                            if hasattr(_ta, "numel") and _ta.numel() > stop_signal_dim:
                                                _chunk_stops.append(float(_ta[stop_signal_dim]))
                                        except Exception:
                                            pass
                            except Exception:
                                pass
                            # Per-subtask stop threshold (e.g. skill 5 = 3) falls
                            # back to the global stop_signal_threshold.
                            _cur_key_for_stop = _subtask_key_from_task(events.get("current_task"))
                            _eff_threshold = _STOP_THRESHOLD_PER_KEY.get(
                                _cur_key_for_stop, stop_signal_threshold
                            )
                            _chunk_stop_index = None
                            if _chunk_stops and _eff_threshold > 0:
                                _chunk_stop_index = first_stop_window(_chunk_stops, _eff_threshold)
                                # Per-subtask "stop early": freeze N actions
                                # before the detected stop window (clamped >=0).
                                _early = _STOP_EARLY_PER_KEY.get(_cur_key_for_stop, 0)
                                _stop_idx_raw = _chunk_stop_index
                                if _chunk_stop_index is not None and _early > 0:
                                    _chunk_stop_index = max(0, _chunk_stop_index - _early)
                                logging.info(
                                    f"[stop-lookahead] subtask={_cur_key_for_stop} "
                                    f"chunk size={len(_chunk_stops)} "
                                    f"threshold={_eff_threshold} "
                                    f"stop_at_index={_chunk_stop_index} "
                                    f"(raw={_stop_idx_raw}, early={_early}) "
                                    f"stops={['%.2f' % v for v in _chunk_stops]}"
                                )
                            _in_chunk_action_idx = 0
                        else:
                            _in_chunk_action_idx += 1

                    action_tensor = torch.tensor([robot_action_to_send[k] for k in action_keys])
                    # On a chunk boundary, smooth over BOUNDARY_INTERP_MULTIPLIER
                    # sub-frames (default 9 = 3x normal). Within a chunk, use the
                    # interpolator's default multiplier (3). After a long
                    # freeze (planner-induced pause), use the larger
                    # LONG_PAUSE_BOUNDARY_MULT for just this first action.
                    if _at_chunk_boundary:
                        _chosen_boundary_mult = (
                            _LONG_PAUSE_BOUNDARY_MULT
                            if _long_pause_boundary_active
                            else _BOUNDARY_INTERP_MULTIPLIER
                        )
                        # Diagnostic: log the L2 gap between current robot pose
                        # and the new chunk's action[0]. A large gap is the
                        # smoking gun for a "burst" — the model is starting the
                        # chunk far from the held freeze pose.
                        if _BOUNDARY_GAP_LOG and interpolator._prev is not None:
                            try:
                                _gap = float((action_tensor - interpolator._prev).norm().item())
                                logging.info(
                                    f"[boundary-gap] |action[0] - current_pose|_L2 = {_gap:.4f} "
                                    f"using multiplier={_chosen_boundary_mult} "
                                    f"long_pause={_long_pause_boundary_active}"
                                )
                            except Exception:
                                pass
                        interpolator.add(action_tensor, multiplier=_chosen_boundary_mult)
                        # The extended multiplier applies ONLY to the first
                        # action after a long pause — clear the flag so the
                        # rest of the chunk (and subsequent chunks) use normal
                        # boundary smoothing.
                        _long_pause_boundary_active = False
                    else:
                        interpolator.add(action_tensor)
                    ran_inference = True

                interp_action = interpolator.get()
                if interp_action is not None:
                    robot_action_to_send = {k: interp_action[i].item() for i, k in enumerate(action_keys)}
                    # Per-arm freeze override on the INTERPOLATED output. The
                    # interpolator buffers raw policy actions whose inactive-arm
                    # values may drift; we force them back to the snapshot pose
                    # on every sub-step so the inactive arm stays still while
                    # the active arm moves smoothly.
                    if frozen_left_state and isinstance(robot_action_to_send, dict):
                        for k, v in frozen_left_state.items():
                            if k in robot_action_to_send:
                                robot_action_to_send[k] = v
                    if frozen_right_state and isinstance(robot_action_to_send, dict):
                        for k, v in frozen_right_state.items():
                            if k in robot_action_to_send:
                                robot_action_to_send[k] = v
                    action_values = robot_action_to_send
                else:
                    continue

                is_record_frame = ran_inference
            else:
                action_values = predict_action(
                    observation=_policy_obs,
                    policy=policy,
                    device=get_safe_torch_device(policy.config.device),
                    preprocessor=preprocessor,
                    postprocessor=postprocessor,
                    use_amp=policy.config.use_amp,
                    # Prefer the live subtask set via keys 1-9/2+a-c (or 'e');
                    # fall back to the umbrella task when nothing is pressed.
                    task=events.get("current_task") or single_task,
                    robot_type=robot.robot_type,
                )
                # Capture the raw policy tensor before it's flattened into a 12-key
                # motor dict — that step drops the stop-signal column (action[12]).
                policy_action_tensor = action_values
                act_processed_policy: RobotAction = make_robot_action(action_values, dataset.features)
                # Applies a pipeline to the action, default is IdentityProcessor
                robot_action_to_send = robot_action_processor((act_processed_policy, obs))
                # Action freeze: override the inactive arm's joint targets with
                # the snapshot taken when this subtask started, so the model can't
                # accidentally move the arm we're trying to hold still.
                if frozen_left_state and isinstance(robot_action_to_send, dict):
                    for k, v in frozen_left_state.items():
                        if k in robot_action_to_send:
                            robot_action_to_send[k] = v
                if frozen_right_state and isinstance(robot_action_to_send, dict):
                    for k, v in frozen_right_state.items():
                        if k in robot_action_to_send:
                            robot_action_to_send[k] = v
                action_values = robot_action_to_send

        elif policy is None and isinstance(teleop, Teleoperator):
            act = teleop.get_action()
            if robot.name == "unitree_g1":
                teleop.send_feedback(obs)

            # Applies a pipeline to the raw teleop action, default is IdentityProcessor
            act_processed_teleop = teleop_action_processor((act, obs))
            action_values = act_processed_teleop
            robot_action_to_send = robot_action_processor((act_processed_teleop, obs))

        elif policy is None and isinstance(teleop, list):
            arm_action = teleop_arm.get_action()
            arm_action = {f"arm_{k}": v for k, v in arm_action.items()}
            keyboard_action = teleop_keyboard.get_action()
            base_action = robot._from_keyboard_to_base_action(keyboard_action)
            act = {**arm_action, **base_action} if len(base_action) > 0 else arm_action
            act_processed_teleop = teleop_action_processor((act, obs))
            action_values = act_processed_teleop
            robot_action_to_send = robot_action_processor((act_processed_teleop, obs))
        else:
            no_action_count += 1
            if no_action_count == 1 or no_action_count % 10 == 0:
                logging.warning(
                    "No policy or teleoperator provided, skipping action generation. "
                    "This is likely to happen when resetting the environment without a teleop device. "
                    "The robot won't be at its rest position at the start of the next episode."
                )
            continue

        # Read stop-signal from the raw policy tensor (action[stop_signal_dim]).
        # `action_values` was overwritten with a 12-key motor dict above, so we
        # use `policy_action_tensor` captured right after predict_action.
        if (
            stop_signal_dim is not None
            and policy is not None
            and policy_action_tensor is not None
        ):
            stop_val = 0.0
            try:
                t = policy_action_tensor.detach().squeeze(0).flatten()
                if t.numel() > stop_signal_dim:
                    stop_val = float(t[stop_signal_dim])
            except Exception as e:
                logging.warning(f"Failed to extract stop signal: {e}")

            stop_signal_history.append(stop_val)

            if display_data:
                try:
                    import rerun as rr
                    rr.log("stop_signal/raw", rr.Scalar(stop_val))
                    if stop_signal_history:
                        avg_1s = sum(stop_signal_history) / len(stop_signal_history)
                        rr.log("stop_signal/avg_1s", rr.Scalar(avg_1s))
                except Exception:
                    pass

            # Legacy time-based debounce — kept for telemetry only. The actual
            # freeze trigger below uses the chunk-level lookahead computed at
            # predict_action time (see [stop-lookahead]).
            if stop_val > 0.5:
                stop_count += 1
            else:
                stop_count = 0
            # Lookahead-based stop: freeze the instant we reach the precomputed
            # start of the consecutive-high stop-signal window within the chunk.
            # `_in_chunk_action_idx` tracks how many actions of THIS chunk have
            # been popped (0 on the first one). `_chunk_stop_index` is None if
            # the chunk contains no window of length >= threshold.
            _stop_trigger = (stop_count >= stop_signal_threshold) if stop_signal_mode == "consecutive" else (
                _chunk_stop_index is not None
                and _in_chunk_action_idx >= _chunk_stop_index
            )
            if _stop_trigger:
                # Track slot occupancy externally so the planner doesn't have to
                # remember which slots are filled. A slot is marked filled ONLY
                # when skill 3 (release) completes immediately after a 2a/2b/2c
                # place — that's the moment the gauze is actually deposited. If
                # a 2x is followed by a 4-recovery (gauze slipped at slot), the
                # slot stays unfilled, which is the correct bookkeeping.
                _just_completed = events.get("current_task")
                events["current_task"] = None
                if (
                    isinstance(_just_completed, str)
                    and "release the gauze by opening" in _just_completed
                    and isinstance(_last_completed_task, str)
                ):
                    if "slots_filled" not in events:
                        events["slots_filled"] = set()
                    if "slot 1" in _last_completed_task:
                        events["slots_filled"].add(1)
                    elif "slot 2" in _last_completed_task:
                        events["slots_filled"].add(2)
                    elif "slot 3" in _last_completed_task:
                        events["slots_filled"].add(3)
                # Remember this completion so the next iteration's release can
                # look back at the slot it was meant to fill.
                if isinstance(_just_completed, str):
                    _last_completed_task = _just_completed
                    # Reset consecutive-timeout counter AND dynamic chunk state
                    # for the just-completed subtask: a clean policy-stop counts
                    # as a success, so the next run of this subtask should
                    # start fresh at DYN_CHUNK_MAX.
                    _completed_key = _subtask_key_from_task(_just_completed)
                    if _completed_key in _DYN_TIMEOUT_KEYS and _completed_key in _consecutive_timeouts:
                        _consecutive_timeouts[_completed_key] = 0
                    if _completed_key in _DYN_CHUNK_KEYS and _dyn_chunk_state.get("last_subtask") == _completed_key:
                        _dyn_chunk_state["last_subtask"] = None
                        _dyn_chunk_state["current"] = None
                        _dyn_chunk_state["executing"] = None
                        _dyn_chunk_state["calls_in_chunk"] = 0
                # Log BEFORE reset so we can see which in-chunk action triggered.
                logging.info(
                    f"Stop signal detected (lookahead)! Freezing robot at "
                    f"in-chunk action #{_in_chunk_action_idx} "
                    f"(stop_at_index was {_chunk_stop_index})"
                )
                if policy is not None:
                    policy.reset()
                stop_count = 0
                # Reset chunk-lookahead state. policy.reset() clears the queue
                # so the next predict_action will be at a fresh boundary and
                # will recompute _chunk_stop_index for the new chunk.
                _chunk_stop_index = None
                _in_chunk_action_idx = 0
                # Snapshot the action we just sent — that's the pose the robot is
                # holding. The freeze loop above will keep re-commanding it until
                # the operator presses a new subtask key.
                if isinstance(robot_action_to_send, dict):
                    # The stop-window action has not been sent. Hold the
                    # observed pose instead of executing that pending target.
                    frozen_action = {k: float(obs[k]) for k in robot.action_features}
                # Mark when this freeze started so the next transition can
                # detect long planner-induced pauses and apply extra smoothing.
                _freeze_started_t = time.perf_counter()
                log_say("task complete", play_sounds=True)
                continue

        # Left-gripper open-offset (subtasks 7/9): add the offset to the gripper
        # COMMAND only (after interpolation, just before send) so the gripper
        # opens a bit wider. `action_values` recorded to the dataset stays
        # un-offset, and the obs fed to the policy was already de-offset above —
        # so this is a pure physical shim that doesn't perturb the model.
        if (
            _LA_GRIPPER_OFFSET != 0.0
            and isinstance(robot_action_to_send, dict)
            and _LA_GRIPPER_KEY in robot_action_to_send
            and _subtask_key_from_task(events.get("current_task")) in _LA_GRIPPER_OFFSET_KEYS
        ):
            try:
                robot_action_to_send[_LA_GRIPPER_KEY] = min(
                    100.0, float(robot_action_to_send[_LA_GRIPPER_KEY]) + _LA_GRIPPER_OFFSET
                )
            except (TypeError, ValueError):
                pass

        # Send action to robot
        # Action can eventually be clipped using `max_relative_target`,
        # so action actually sent is saved in the dataset. action = postprocessor.process(action)
        # TODO(steven, pepijn, adil): we should use a pipeline step to clip the action, so the sent action is the action that we input to the robot.
        _sent_action = robot.send_action(robot_action_to_send)

        # Write to dataset (only on real policy frames, not interpolated-only iterations)
        if dataset is not None and is_record_frame:
            action_frame = build_dataset_frame(dataset.features, action_values, prefix=ACTION)
            # Prefer the currently-selected subtask label (set via keys 1-6) and
            # fall back to the episode-level umbrella task string.
            frame_task = events.get("current_task") or single_task
            if frame_task == "subtask finished":
                frame_task = IDLE_LABEL
            frame = {**observation_frame, **action_frame, "task": frame_task}
            dataset.add_frame(frame)

        if display_data:
            if not globals().get("_DEPTH_KEYS_DUMPED"):
                globals()["_DEPTH_KEYS_DUMPED"] = True
                import numpy as _np
                logging.info(f"DISPLAY-KEYS raw-obs={list(obs.keys())}")
                logging.info(f"DISPLAY-KEYS processed={list(obs_processed.keys())}")
            log_rerun_data(
                # display-only: carry raw depth views through (undeclared in dataset features)
                observation={**obs_processed, **{k: v for k, v in obs.items() if k.endswith("_depth")}},
                action=action_values, compress_images=display_compressed_images
            )

        dt_s = time.perf_counter() - start_loop_t

        sleep_time_s: float = control_interval - dt_s
        if sleep_time_s < 0:
            logging.warning(
                f"Record loop is running slower ({1 / dt_s:.1f} Hz) than the target FPS ({fps} Hz). Dataset frames might be dropped and robot control might be unstable. Common causes are: 1) Camera FPS not keeping up 2) Policy inference taking too long 3) CPU starvation"
            )

        precise_sleep(max(sleep_time_s, 0.0))

        timestamp = time.perf_counter() - start_episode_t


# Live reference to the keyboard_listener events dict, set in record() right
# after init_keyboard_listener. External wrappers (v3 autosubtask LM head) write
# their generated subtask into events["current_task"] through this reference so
# all per-key features (dyn-chunk, dyn-timeout, gripper offset, ...) trigger as
# if the operator had pressed the subtask key.
_active_events: dict | None = None


class _JsonlLogHandler(logging.Handler):
    """Logging handler that writes one JSON object per log record to a .jsonl file.

    Captures EVERY log record emitted during a run (planner decisions,
    [stop-lookahead]/[dyn-timeout]/[la-gripper-offset] events, warnings,
    errors, ...) so the whole inference session is replayable from a single
    structured file. Opened line-buffered so each record is flushed on write.
    """

    def __init__(self, path: str):
        super().__init__()
        self._fh = open(path, "a", buffering=1)  # line-buffered
        self.path = path

    def emit(self, record):
        import json
        try:
            obj = {
                "ts": record.created,
                "time": time.strftime("%Y-%m-%dT%H:%M:%S", time.localtime(record.created))
                + f".{int(record.msecs):03d}",
                "level": record.levelname,
                "logger": record.name,
                "module": record.module,
                "line": record.lineno,
                "msg": record.getMessage(),
            }
            if record.exc_info:
                obj["exc"] = logging.Formatter().formatException(record.exc_info)
            self._fh.write(json.dumps(obj, ensure_ascii=False, default=str) + "\n")
        except Exception:
            # Logging must never crash the control loop.
            pass

    def close(self):
        try:
            self._fh.close()
        except Exception:
            pass
        super().close()


def _attach_jsonl_log_handler(dataset_root):
    """Attach a JSONL log handler to the root logger if INFERENCE_LOG_JSONL is set.

    INFERENCE_LOG_JSONL:
      - unset / "0" / "off" / "false" -> disabled (returns None).
      - "1" / "auto" / "on" / "true"  -> <dataset_root_parent>/inference_logs/<root_basename>_<ts>.jsonl
      - any other value               -> treated as an explicit output file path.

    NOTE: the auto path writes to a SIBLING `inference_logs/` dir in the dataset
    root's PARENT — never inside the dataset root, and never creating the root
    itself. Creating the root here would break LeRobotDataset.create()'s
    `mkdir(exist_ok=False)` on a fresh run (the cause of an earlier FileExistsError).
    """
    import os

    val = os.environ.get("INFERENCE_LOG_JSONL", "").strip()
    if val == "" or val.lower() in ("0", "off", "false", "no"):
        return None
    if val.lower() in ("1", "auto", "on", "true", "yes"):
        root = os.path.normpath(str(dataset_root)) if dataset_root else "."
        parent = os.path.dirname(root) or "."
        base = os.path.basename(root) or "run"
        log_dir = os.path.join(parent, "inference_logs")  # sibling of the dataset root
        os.makedirs(log_dir, exist_ok=True)
        path = os.path.join(log_dir, f"{base}_{time.strftime('%Y%m%d_%H%M%S')}.jsonl")
    else:
        path = val
        _d = os.path.dirname(path)
        if _d:
            os.makedirs(_d, exist_ok=True)
    try:
        handler = _JsonlLogHandler(path)
    except Exception as _e:
        logging.warning(f"[jsonl-log] could not open {path}: {_e}; JSONL logging disabled")
        return None
    handler.setLevel(logging.INFO)
    logging.getLogger().addHandler(handler)
    logging.info(f"[jsonl-log] saving all inference logs to {path}")
    return handler


@parser.wrap()
def record(cfg: RecordConfig) -> LeRobotDataset:
    init_logging()
    _jsonl_log_handler = _attach_jsonl_log_handler(cfg.dataset.root)
    logging.info(pformat(asdict(cfg)))
    if cfg.display_data:
        init_rerun(session_name="recording", ip=cfg.display_ip, port=cfg.display_port)
        # EXPLICIT layout: two image views side by side (the auto-heuristic can stack
        # same-sized images as layers in ONE view, hiding depth beneath the RGB)
        try:
            import rerun as rr
            import rerun.blueprint as rrb
            rr.send_blueprint(rrb.Blueprint(
                rrb.Grid(
                    rrb.Spatial2DView(name="wrist RGB", origin="observation.wrist"),
                    rrb.Spatial2DView(name="wrist DEPTH", origin="observation.wrist_depth"),
                    rrb.TimeSeriesView(name="joints & action", origin="/"),
                ),
                collapse_panels=False,
            ), make_active=True, make_default=True)
            logging.info("explicit blueprint sent (RGB + DEPTH views)")
        except Exception as e:
            logging.warning(f"blueprint send failed: {type(e).__name__}: {e}")
    display_compressed_images = (
        True
        if (cfg.display_data and cfg.display_ip is not None and cfg.display_port is not None)
        else cfg.display_compressed_images
    )

    robot = make_robot_from_config(cfg.robot)
    teleop = make_teleoperator_from_config(cfg.teleop) if cfg.teleop is not None else None

    teleop_action_processor, robot_action_processor, robot_observation_processor = make_default_processors()

    dataset_features = combine_feature_dicts(
        aggregate_pipeline_dataset_features(
            pipeline=teleop_action_processor,
            initial_features=create_initial_features(
                action=robot.action_features
            ),  # TODO(steven, pepijn): in future this should be come from teleop or policy
            use_videos=cfg.dataset.video,
        ),
        aggregate_pipeline_dataset_features(
            pipeline=robot_observation_processor,
            initial_features=create_initial_features(observation=robot.observation_features),
            use_videos=cfg.dataset.video,
        ),
    )

    dataset = None
    listener = None

    try:
        if cfg.resume:
            num_cameras = len(robot.cameras) if hasattr(robot, "cameras") else 0
            dataset = LeRobotDataset.resume(
                cfg.dataset.repo_id,
                root=cfg.dataset.root,
                batch_encoding_size=cfg.dataset.video_encoding_batch_size,
                vcodec=cfg.dataset.vcodec,
                streaming_encoding=cfg.dataset.streaming_encoding,
                encoder_queue_maxsize=cfg.dataset.encoder_queue_maxsize,
                encoder_threads=cfg.dataset.encoder_threads,
                image_writer_processes=cfg.dataset.num_image_writer_processes if num_cameras > 0 else 0,
                image_writer_threads=cfg.dataset.num_image_writer_threads_per_camera * num_cameras
                if num_cameras > 0
                else 0,
            )
            sanity_check_dataset_robot_compatibility(dataset, robot, cfg.dataset.fps, dataset_features)
        else:
            # Create empty dataset or load existing saved episodes
            sanity_check_dataset_name(cfg.dataset.repo_id, cfg.policy)
            dataset = LeRobotDataset.create(
                cfg.dataset.repo_id,
                cfg.dataset.fps,
                root=cfg.dataset.root,
                robot_type=robot.name,
                features=dataset_features,
                use_videos=cfg.dataset.video,
                image_writer_processes=cfg.dataset.num_image_writer_processes,
                image_writer_threads=cfg.dataset.num_image_writer_threads_per_camera * len(robot.cameras),
                batch_encoding_size=cfg.dataset.video_encoding_batch_size,
                vcodec=cfg.dataset.vcodec,
                streaming_encoding=cfg.dataset.streaming_encoding,
                encoder_queue_maxsize=cfg.dataset.encoder_queue_maxsize,
                encoder_threads=cfg.dataset.encoder_threads,
            )

        if cfg.canonical_task_labels is not None:
            if cfg.resume:
                for task_id, label in enumerate(cfg.canonical_task_labels):
                    if dataset.meta.get_task_index(label) != task_id:
                        raise ValueError("Cannot resume: dataset task IDs differ from the canonical task table")
            else:
                dataset.meta.save_episode_tasks(cfg.canonical_task_labels)

        # PRE-MAKE_POLICY shape fix for stop_signal-augmented checkpoints.
        # The checkpoint's action layers are sized for (N+1) outputs (N joints
        # + stop signal) but the recording dataset only stores N-dim actions.
        # make_policy() reads dataset.meta to build the action head; without
        # this temporary inflation it would create an N-dim head and fail to
        # load the (N+1)-dim weights (fatal for ACT; pi0.5 silently works via
        # max_action_dim padding). We inflate the meta only for the duration
        # of make_policy, then restore so the dataset writer continues to
        # validate per-frame actions as N-dim.
        _restore_action_feat = None
        if cfg.policy is not None and cfg.stop_signal_dim is not None:
            from lerobot.utils.constants import ACTION as _ACTION
            _af = dataset.meta.features.get(_ACTION)
            if _af is not None:
                _shape = _af.get("shape")
                if _shape and len(_shape) >= 1 and _shape[0] == cfg.stop_signal_dim:
                    _restore_action_feat = _af  # remember the N-dim version
                    _af_inflated = dict(_af)
                    _af_inflated["shape"] = (cfg.stop_signal_dim + 1,) + tuple(_shape[1:])
                    dataset.meta.features[_ACTION] = _af_inflated

        # Load pretrained policy
        policy = (
            None
            if cfg.policy is None
            else make_policy(cfg.policy, ds_meta=dataset.meta, rename_map=cfg.dataset.rename_map)
        )

        # Restore the dataset meta's action shape to N-dim so per-frame
        # validation in the writer continues to expect N motor joints.
        if _restore_action_feat is not None:
            from lerobot.utils.constants import ACTION as _ACTION
            dataset.meta.features[_ACTION] = _restore_action_feat

        # When --stop_signal_dim is set, the policy's action chunk is N+1 wide
        # (N motor joints plus a stop-signal scalar at index stop_signal_dim).
        # `make_policy` overwrites cfg.output_features with the recording dataset's
        # action shape (N motors only), causing predict_action_chunk to truncate
        # away the stop-signal column and break the (N+1)-dim postprocessor stats.
        # Restore the +1 dim so the model output matches the saved normalizer.
        if cfg.stop_signal_dim is not None and policy is not None:
            from lerobot.configs.types import FeatureType, PolicyFeature
            from lerobot.utils.constants import ACTION

            action_feat = policy.config.output_features.get(ACTION)
            if action_feat is not None and action_feat.shape[0] == cfg.stop_signal_dim:
                policy.config.output_features[ACTION] = PolicyFeature(
                    type=FeatureType.ACTION,
                    shape=(cfg.stop_signal_dim + 1,),
                )
        preprocessor = None
        postprocessor = None
        interpolator = None
        if cfg.policy is not None:
            preprocessor, postprocessor = make_pre_post_processors(
                policy_cfg=cfg.policy,
                pretrained_path=cfg.policy.pretrained_path,
                dataset_stats=rename_stats(dataset.meta.stats, cfg.dataset.rename_map),
                preprocessor_overrides={
                    "device_processor": {"device": cfg.policy.device},
                    "rename_observations_processor": {"rename_map": cfg.dataset.rename_map},
                },
            )
            # Create interpolator for smoother policy control
            if cfg.interpolation_multiplier > 1:
                interpolator = ActionInterpolator(multiplier=cfg.interpolation_multiplier)
                logging.info(f"Action interpolation enabled: {cfg.interpolation_multiplier}x control rate")

        robot.connect(calibrate=cfg.calibrate_on_connect)
        if teleop is not None:
            teleop.connect(calibrate=cfg.calibrate_on_connect)

        home_pose: dict[str, float] | None = None
        if cfg.home_pose_file:
            if not Path(cfg.home_pose_file).is_file():
                logging.warning(
                    "home_pose_file=%s does not exist; auto-home between episodes disabled.",
                    cfg.home_pose_file,
                )
            else:
                home_pose = {}
                with open(cfg.home_pose_file) as _f:
                    for _line in _f:
                        _line = _line.strip()
                        if "=" in _line:
                            _k, _v = _line.split("=", 1)
                            home_pose[_k] = float(_v)
                logging.info(
                    "Auto-home between episodes enabled. Pose loaded from %s (%d joints).",
                    cfg.home_pose_file,
                    len(home_pose),
                )

        active_subtasks = (
            _build_active_subtasks(cfg.subtask_slot_n)
            if (cfg.subtask_slot_n is not None or cfg.enable_subtasks)
            else None
        )
        if active_subtasks:
            logging.info(
                "Subtask keymap active. Press keys during recording to tag frames:\n%s",
                "\n".join(f"  {k} -> {v}" for k, v in active_subtasks.items()),
            )
            logging.info(
                "Slot-templated keys (containing '{N}') are two-stage: press the "
                "digit, then press 'a'/'b'/'c' to choose slot 1/2/3. The resolved "
                "label is applied to subsequent frames."
            )
            logging.info(
                "Subtask control: 'e' tags subsequent frames as 'subtask finished' (end-of-phase marker)."
            )
            logging.info(
                "Episode control: Enter=end, ESC=stop, Backspace=re-record (arrows also work)."
            )
        listener, events = init_keyboard_listener(
            subtasks=active_subtasks,
            subtask_voices=SUBTASK_VOICES if active_subtasks else None,
            play_sounds=cfg.play_sounds,
        )
        # Expose the live events dict at module level so external wrappers
        # (e.g. the v3 autosubtask wrapper) can bridge their LM-decoded subtask
        # into events["current_task"] — that's what every per-key feature
        # (dyn-chunk, dyn-timeout, gripper offset, ...) reads via
        # _subtask_key_from_task(events.get("current_task")). Without this
        # bridge, the wrapper's task override only reaches predict_action's
        # `task` arg and the per-key gates silently never fire.
        global _active_events
        _active_events = events

        # Initialize the optional high-level planner. Lazy import keeps the SDK
        # dependency optional — only loaded when the matching --planner is set.
        planner = None
        if cfg.planner == "gemini":
            from lerobot.common.gemini_planner import GeminiPlanner
            log_dir = cfg.planner_log_dir or str(
                Path(cfg.dataset.root or ".") / "planner_trace"
                if cfg.dataset.root else "outputs/planner_trace"
            )
            planner = GeminiPlanner(
                subtask_labels=SUBTASK_LABELS,
                dry_run=cfg.planner_dry_run,
                cooldown_s=cfg.planner_cooldown_s,
                model=cfg.planner_model,
                speak=cfg.play_sounds,
                log_dir=log_dir,
                confirm_required=cfg.planner_confirm_required,
            )
            logging.info(
                "Gemini planner enabled (model=%s, dry_run=%s, confirm_required=%s). "
                "Operator keyboard always wins; planner only fires when current_task is None during freeze.",
                cfg.planner_model, cfg.planner_dry_run, cfg.planner_confirm_required,
            )
        elif cfg.planner is not None:
            raise ValueError(f"Unsupported planner: {cfg.planner!r}")

        if not cfg.dataset.streaming_encoding:
            logging.info(
                "Streaming encoding is disabled. If you have capable hardware, consider enabling it for way faster episode saving. --dataset.streaming_encoding=true --dataset.encoder_threads=2 # --dataset.vcodec=auto. More info in the documentation: https://huggingface.co/docs/lerobot/streaming_video_encoding"
            )

        with VideoEncodingManager(dataset):
            recorded_episodes = 0
            while recorded_episodes < cfg.dataset.num_episodes and not events["stop_recording"]:
                log_say(f"Recording episode {dataset.num_episodes}", cfg.play_sounds)
                # Clear stale subtask label so each episode starts on the umbrella task
                # until the operator presses a subtask key.
                events["current_task"] = None
                # Reset slot occupancy and planner conversation state for a fresh episode.
                events["slots_filled"] = set()
                if planner is not None:
                    planner.reset_history()
                record_loop(
                    robot=robot,
                    events=events,
                    fps=cfg.dataset.fps,
                    teleop_action_processor=teleop_action_processor,
                    robot_action_processor=robot_action_processor,
                    robot_observation_processor=robot_observation_processor,
                    teleop=teleop,
                    policy=policy,
                    preprocessor=preprocessor,
                    postprocessor=postprocessor,
                    dataset=dataset,
                    control_time_s=cfg.dataset.episode_time_s,
                    single_task=cfg.dataset.single_task,
                    display_data=cfg.display_data,
                    interpolator=interpolator,
                    display_compressed_images=display_compressed_images,
                    stop_signal_dim=cfg.stop_signal_dim,
                    stop_signal_threshold=cfg.stop_signal_threshold,
                    stop_signal_mode=cfg.stop_signal_mode,
                    home_pose_file=cfg.home_pose_file,
                    enable_subtasks=cfg.enable_subtasks,
                    cam_mask_per_subtask=cfg.cam_mask_per_subtask,
                    image_keys_openpi_style=cfg.image_keys_openpi_style,
                    burst_select_n=cfg.burst_select_n,
                    planner=planner,
                    blue_confidence_threshold=cfg.planner_blue_confidence_threshold,
                )

                # Execute a few seconds without recording to give time to manually reset the environment
                # Skip reset for the last episode to be recorded
                if not events["stop_recording"] and (
                    (recorded_episodes < cfg.dataset.num_episodes - 1) or events["rerecord_episode"]
                ):
                    # Optional auto-home: drive both arms to the saved home pose
                    # before the teleop reset phase so the operator doesn't have
                    # to home manually. Send action directly (bypasses teleop).
                    if home_pose is not None:
                        log_say("Going home", cfg.play_sounds)
                        _home_steps = max(1, int(cfg.home_duration_s / 0.05))
                        for _ in range(_home_steps):
                            robot.send_action(home_pose)
                            time.sleep(0.05)

                    if cfg.dataset.reset_wait_enter:
                        log_say("Reset, press Enter when ready", cfg.play_sounds)
                        # Very large timeout; Enter sets exit_early and breaks the loop.
                        _reset_ctl_s: float = 24 * 3600
                    else:
                        log_say("Reset the environment", cfg.play_sounds)
                        _reset_ctl_s = cfg.dataset.reset_time_s

                    record_loop(
                        robot=robot,
                        events=events,
                        fps=cfg.dataset.fps,
                        teleop_action_processor=teleop_action_processor,
                        robot_action_processor=robot_action_processor,
                        robot_observation_processor=robot_observation_processor,
                        teleop=teleop,
                        control_time_s=_reset_ctl_s,
                        single_task=cfg.dataset.single_task,
                        display_data=cfg.display_data,
                    )

                if events.get("go_home"):
                    log_say("Going home and restarting", cfg.play_sounds)
                    events["go_home"] = False
                    events["exit_early"] = False
                    events["current_task"] = None
                    dataset.clear_episode_buffer()
                    if home_pose is not None:
                        _home_steps = max(1, int(cfg.home_duration_s / 0.05))
                        for _ in range(_home_steps):
                            robot.send_action(home_pose)
                            time.sleep(0.05)
                    if policy is not None:
                        policy.reset()
                    continue

                if events["rerecord_episode"]:
                    log_say("Re-record episode", cfg.play_sounds)
                    events["rerecord_episode"] = False
                    events["exit_early"] = False
                    dataset.clear_episode_buffer()
                    continue

                _clean_drop_segments(dataset)
                # Skip saving an empty episode. This happens when the operator
                # ends an episode before any policy frame was recorded — e.g.
                # pressing Enter during the initial Gemini freeze (the robot is
                # frozen waiting for the planner's first pick, and the freeze
                # loop `continue`s before reaching dataset.add_frame). Calling
                # save_episode() with zero frames raises in validate_episode_buffer.
                if not dataset.has_pending_frames():
                    logging.warning(
                        "Episode had 0 recorded frames (ended before any policy "
                        "action executed) — skipping save, not counting it."
                    )
                    dataset.clear_episode_buffer()
                    continue
                dataset.save_episode()
                recorded_episodes += 1
    finally:
        log_say("Stop recording", cfg.play_sounds, blocking=True)

        if dataset:
            dataset.finalize()

        if robot.is_connected:
            robot.disconnect()
        if teleop and teleop.is_connected:
            teleop.disconnect()

        if not is_headless() and listener:
            listener.stop()

        if cfg.dataset.push_to_hub:
            dataset.push_to_hub(tags=cfg.dataset.tags, private=cfg.dataset.private)

        log_say("Exiting", cfg.play_sounds)

        if _jsonl_log_handler is not None:
            try:
                logging.getLogger().removeHandler(_jsonl_log_handler)
                _jsonl_log_handler.close()
            except Exception:
                pass
    return dataset


def main():
    register_third_party_plugins()
    record()


if __name__ == "__main__":
    main()
